P = [
 dict(pmid='', doi='10.64898/2026.11.16.26368211', journal='medRxiv', title='Modifiable and Context-Specific Factors Associated with Dementia in the Democratic Republic of the Congo: A Community-Derived Cross-Sectional Study', tier='C', basis='Not stated', short='DR Congo 721-person cross-sectional sample: poverty, low resilience and depression associated with dementia; PM2.5 not associated (medRxiv)', design='Cross-sectional', pm='PM2.5 one of 16 social, behavioural and environmental factors (source not stated in abstract)', geo='DR Congo (Kinshasa)', endpoint='Dementia status (including suspected Alzheimer disease)', affil='Emory University School of Medicine, USA; University of Navarra, Spain', n='medRxiv preprint. 721 participants in the Democratic Republic of the Congo (232 cognitively unimpaired, 489 with dementia including 247 suspected AD); logistic regression on 16 factors with age, sex and missing-category indicators. Adding the factors raised Nagelkerke R2 from 0.106 to 0.368. Poverty (aOR 2.34, 95% CI 1.52-3.60), low resilience (1.84, 1.18-2.86) and depression (1.53, 1.02-2.31) were associated with dementia; higher education inversely (0.51, 0.39-0.66 per SD). PM2.5 exposure was not significantly associated; no estimate is given. Weakness: cross-sectional, non-representative and dementia-enriched sampling, mean imputation, and an unnamed PM2.5 source in a region with almost no ground monitoring. Relevance: Central Africa has near-zero reference monitoring; a null here says more about exposure data than about PM2.5 and dementia.', sub=corpus.NEU),
 dict(pmid='43063086', doi='10.1097/md.0000000000051552', journal='Medicine (Baltimore)', title='Global inequalities in subarachnoid hemorrhage attributable to temperature extremes and air pollution among adults over 40 years: Insights from the GBD study with projections to 2050.', tier='C', basis='Model (CTM / LUR / ML)', short='GBD 2021, adults 40+: ambient PM the largest environmental contributor to subarachnoid-haemorrhage deaths (50,936 in 2021), projected 65,847 by 2050', design='Burden of disease (GBD)', pm='GBD 2021 ambient particulate matter, household air pollution, high and low temperature risk factors', geo='Global / multi-region', endpoint='Subarachnoid haemorrhage deaths and DALYs attributable to environmental risks', affil='Xiangya Hospital, Central South University, China; Xiangya Hospital, Central South University, China', n='Secondary analysis of GBD 2021 for adults aged 40+ in 204 countries: SAH burden attributable to ambient PM, household air pollution and temperature extremes, trends 1990-2021, ARIMA and exponential-smoothing projections to 2050 and decomposition. In 2021 ambient PM accounted for 50,936 SAH deaths and 1,357,090 DALYs, more than household air pollution (32,224 deaths) or low temperature (18,648). Ambient-PM-attributable deaths rose from 35,329 in 1990, while household-air-pollution deaths fell from 77,441; projections reach 65,847 ambient-PM deaths by 2050. Burden was higher in males. Weakness: GBD attributable estimates inherit its exposure surfaces and integrated exposure-response curves; the SAH-specific relative risk is borrowed from stroke evidence; no uncertainty intervals in the abstract. Relevance: none directly; GBD surfaces in low-income regions are the least validated by ground sensors.', sub=corpus.BURD),
 dict(pmid='43063598', doi='10.1016/j.phymed.2026.158920', journal='Phytomedicine', title='Liriopesides B ameliorates fine particulate matter-induced lung injury by directly targeting ubiquitin-conjugating enzyme E2 Q2 to dismantle the macrophage lactylation-neutrophil extracellular trap axis.', tier='C', basis='Not stated', short='Mouse PM2.5 lung injury: macrophage glycolysis and lactylation drive neutrophil extracellular traps via UBE2Q2/LDHA', design='Animal exposure study + in vitro', pm='PM2.5 exposure in mice; dose and particle source not stated in the abstract', geo='China (laboratory)', endpoint='PM2.5-induced lung injury; macrophage lactylation and neutrophil extracellular traps', affil='Chengdu Institute of Respiratory Health, Southwest Jiaotong University, China; Chengdu Institute of Respiratory Health, Southwest Jiaotong University, China', n='Mechanistic study combining single-cell RNA sequencing, surface plasmon resonance, docking and a macrophage-depleted adoptive-transfer mouse model. PM2.5 reprogrammed pulmonary macrophages towards a hyper-glycolytic, lactylation-driven state that paracrinally drove neutrophil chemotaxis and extracellular-trap formation; the E2 enzyme UBE2Q2 acted as the checkpoint regulating LDHA to sustain the cascade, and a plant-derived inhibitor of that axis reduced injury. No exposure-response relationship and no effect sizes with CIs are reported. Weakness: laboratory PM2.5 of unstated origin and concentration, so no dose can be mapped to ambient exposure; the mechanism rests on a single pathway readout. Relevance: none to measurement, but lactylation as an intermediate would need composition-resolved exposure, not mass alone.', sub=corpus.MECH),
 dict(pmid='43050116', doi='10.1007/s11356-026-38376-6', journal='Environmental science and pollution research international', title='Model pollution iron-rich silica particulate: impairment of glutamate/GABA balance and ROS generation in brain nerve terminals.', tier='C', basis='Lab / research instrument', short='Synthetic iron-rich silica core-shell particles raise extracellular GABA and glutamate in rat synaptosomes, size- and dose-dependently (0.1-1.0 mg/ml)', design='In vitro', pm='Synthesised Fe3O4@SiO2 core-shell nanoparticles characterised by TEM, SEM, DLS, SAED and XRD; 0.1-1.0 mg/ml', geo='Ukraine (laboratory)', endpoint='Extracellular glutamate and GABA levels and ROS generation in rat brain nerve terminals', affil='L. V. Pisarzhevskii Institute of Physical Chemistry, National Academy of Sciences, Ukraine; same institute, Ukraine', n='Model multipollutant iron-rich silica particles (Fe3O4@SiO2 core-shell, varying constituent proportions) applied to isolated rat brain synaptosomes at 0.1-1.0 mg/ml. Extracellular radiolabelled glutamate and GABA rose with particle size and dose, GABA being the more sensitive readout; the particles reduced spontaneous, H2O2- and kainate-induced ROS generation, interacted with the synaptosomal membrane and added to the effects of Cu2+, Pb2+ and Cd2+ rather than mitigating them. No CIs are reported. Weakness: milligram-per-millilitre doses of synthetic particles are orders of magnitude above realistic deposited lung or brain doses, and synaptosomes bypass every biological barrier. Relevance: supports interest in the iron fraction of ambient PM, which optical sensors cannot see at all.', sub=corpus.MECH),
]
